-- V90.ag Dispatch execution / stock depletion / invoice linkage
CREATE TABLE IF NOT EXISTS dispatches (dispatch_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, location_id TEXT NOT NULL, warehouse_id TEXT NOT NULL, sales_order_id TEXT NOT NULL, pick_list_id TEXT NOT NULL, dispatch_no TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'DRAFT', vehicle_no TEXT NULL, transporter TEXT NULL, eway_bill_no TEXT NULL, notes TEXT NULL, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, posted_at TEXT NULL);
CREATE TABLE IF NOT EXISTS dispatch_lines (dispatch_line_id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL, sales_order_line_id TEXT NOT NULL, sales_order_allocation_id TEXT NOT NULL, sku_id TEXT NOT NULL, packed_fg_lot_id TEXT NOT NULL, lot_code TEXT NULL, dispatched_qty NUMERIC NOT NULL, uom TEXT NOT NULL DEFAULT 'kg', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales_invoices (invoice_id TEXT PRIMARY KEY, organization_id TEXT NOT NULL, entity_id TEXT NOT NULL, location_id TEXT NOT NULL, sales_order_id TEXT NOT NULL, dispatch_id TEXT NOT NULL, invoice_no TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'POSTED', subtotal NUMERIC NOT NULL DEFAULT 0, discount_total NUMERIC NOT NULL DEFAULT 0, taxable_value NUMERIC NOT NULL DEFAULT 0, gst_total NUMERIC NOT NULL DEFAULT 0, grand_total NUMERIC NOT NULL DEFAULT 0, created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales_invoice_lines (invoice_line_id TEXT PRIMARY KEY, invoice_id TEXT NOT NULL, sales_order_line_id TEXT NOT NULL, sku_id TEXT NOT NULL, quantity NUMERIC NOT NULL, unit_price NUMERIC NOT NULL, discount_amount NUMERIC NOT NULL DEFAULT 0, taxable_amount NUMERIC NOT NULL DEFAULT 0, gst_rate NUMERIC NOT NULL DEFAULT 0, gst_amount NUMERIC NOT NULL DEFAULT 0, line_total NUMERIC NOT NULL DEFAULT 0);
